#!/usr/bin/env bash

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

require_pattern() {
  local description="$1"
  local pattern="$2"
  local file="$3"
  if ! rg -n --fixed-strings "${pattern}" "${file}" >/dev/null; then
    echo "[limit-pct-guard] missing ${description}: ${pattern} (${file})"
    exit 1
  fi
}

echo "[limit-pct-guard] checking limit_pct integration guards"

require_pattern "backend query param" "limit_pct: float = Query(default=10.0, ge=0.1, le=30.0)" "${ROOT_DIR}/backend/app/main.py"
require_pattern "analysis finite-limit guard" "math.isfinite(limit_pct)" "${ROOT_DIR}/backend/app/analysis.py"
require_pattern "analysis non-finite fallback" "else 10.0" "${ROOT_DIR}/backend/app/analysis.py"
require_pattern "analysis limit rule echo" "\"limit_rule\": f\"prev_close_{normalized_limit_pct:g}pct\"" "${ROOT_DIR}/backend/app/analysis.py"
require_pattern "frontend option field" "limitPct: number;" "${ROOT_DIR}/frontend/src/api.ts"
require_pattern "frontend request param" "params.set(\"limit_pct\", String(options.limitPct));" "${ROOT_DIR}/frontend/src/api.ts"
require_pattern "app option clamp" "limitPct: clampNumber(Number(limitPct), 0.1, 30, 10)," "${ROOT_DIR}/frontend/src/App.tsx"
require_pattern "api test NaN limit reject" "limit_pct=NaN" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test nan limit reject" "limit_pct=nan" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced NaN limit reject" "limit_pct=%20NaN%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced nan limit reject" "limit_pct=%20nan%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test Infinity limit reject" "limit_pct=Infinity" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test inf limit reject" "limit_pct=inf" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test +Infinity limit reject" "limit_pct=%2BInfinity" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test +inf limit reject" "limit_pct=%2Binf" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced Infinity limit reject" "limit_pct=%20Infinity%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced inf limit reject" "limit_pct=%20inf%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced +Infinity limit reject" "limit_pct=%20%2BInfinity%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced +inf limit reject" "limit_pct=%20%2Binf%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test -Infinity limit reject" "limit_pct=-Infinity" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test -inf limit reject" "limit_pct=-inf" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced -Infinity limit reject" "limit_pct=%20-Infinity%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test spaced -inf limit reject" "limit_pct=%20-inf%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow positive limit reject" "limit_pct=1e309" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow positive plus limit reject" "limit_pct=%2B1e309" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow positive spaced limit reject" "limit_pct=%201e309%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow positive plus spaced limit reject" "limit_pct=%20%2B1e309%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow negative limit reject" "limit_pct=-1e309" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test overflow negative spaced limit reject" "limit_pct=%20-1e309%20" "${ROOT_DIR}/backend/tests/test_api.py"
