require_pattern "api test scientific too-large reject" "limit_pct=3.01e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus too-small reject" "limit_pct=%2B9e-2" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus too-large reject" "limit_pct=%2B3.01e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific negative too-small spaced reject" "limit_pct=%20-9e-2%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific negative too-large spaced reject" "limit_pct=%20-3.01e1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation limit" "limit_pct=1e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation rule" "assert scientific_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation upper limit" "limit_pct=1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation upper rule" "assert scientific_limit_upper_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
