require_pattern "api test scientific notation plus rule" "assert unconstrained_scientific_plus_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation plus upper limit" "limit_pct=%2B1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation plus upper rule" "assert unconstrained_scientific_plus_upper_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation plus upper spaced limit" "limit_pct=%20%2B1E1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific notation plus upper spaced rule" "assert unconstrained_scientific_plus_upper_spaced_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test decimal plus limit" "limit_pct=%2B12.5" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test decimal plus rule" "assert unconstrained_decimal_plus_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_12.5pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test decimal plus spaced limit" "limit_pct=%20%2B12.5%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test decimal plus spaced rule" "assert unconstrained_decimal_plus_spaced_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_12.5pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test min plus limit" "limit_pct=%2B0.1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test min plus rule" "assert plus_min_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_0.1pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
