require_pattern "api test unconstrained scientific notation upper rule" "assert unconstrained_scientific_upper_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific min limit" "limit_pct=1e-1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific min rule" "assert scientific_min_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_0.1pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus min limit" "limit_pct=%2B1e-1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus min rule" "assert scientific_plus_min_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_0.1pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific max limit" "limit_pct=3e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific max rule" "assert scientific_max_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_30pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus max limit" "limit_pct=%2B3e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "api test scientific plus max rule" "assert scientific_plus_max_limit_payload[\"params\"][\"limit_rule\"] == \"prev_close_30pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=1e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation upper limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation plus limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%2B1e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation plus upper limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%2B1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation plus upper spaced limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%20%2B1E1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation plus spaced limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%20%2B1e1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained scientific notation plus min limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%2B1e-1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=1e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation upper limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation plus limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%2B1e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation plus upper limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%2B1E1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation plus upper spaced limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%20%2B1E1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation plus spaced limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%20%2B1e1%20" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained scientific notation plus max limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%2B3e1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave unconstrained decimal plus limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=false&limit_pct=%2B12.5" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave constrained min plus limit" "strategy=wave_zigzag_reversal&threshold_pct=8&apply_limit_constraints=true&limit_pct=%2B0.1" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation unconstrained rule" "assert unconstrained_scientific_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation constrained rule" "assert constrained_scientific_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation constrained plus rule" "assert constrained_scientific_plus_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation constrained plus upper rule" "assert constrained_scientific_plus_upper_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation constrained plus upper spaced rule" "assert constrained_scientific_plus_upper_spaced_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation constrained plus spaced rule" "assert constrained_scientific_plus_spaced_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation unconstrained plus rule" "assert unconstrained_scientific_plus_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation unconstrained plus upper rule" "assert unconstrained_scientific_plus_upper_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
require_pattern "wave scientific notation unconstrained plus upper spaced rule" "assert unconstrained_scientific_plus_upper_spaced_payload[\"params\"][\"limit_rule\"] == \"prev_close_10pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
