require_pattern "wave scientific notation unconstrained plus min rule" "assert unconstrained_scientific_plus_min_payload[\"params\"][\"limit_rule\"] == \"prev_close_0.1pct\"" "${ROOT_DIR}/backend/tests/test_api.py"
